        automatic logic [31:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.intsta.value.value;
        load_next_c = '0;
        if(hwif_in.intsta.value.we) begin // HW Write - we
            next_c = hwif_in.intsta.value.next;
            load_next_c = '1;
        end
        field_combo.intsta.value.next = next_c;
        field_combo.intsta.value.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge arst_n) begin
        if(~arst_n) begin
            field_storage.intsta.value.value <= 32'h0;
        end else begin
            if(field_combo.intsta.value.load_next) begin
                field_storage.intsta.value.value <= field_combo.intsta.value.next;
            end
        end
    end
    assign hwif_out.intsta.value.value = field_storage.intsta.value.value;

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    // Writes are always granted with no error response, unless an optional
    // policy check reports one.
    assign cpuif_wr_err = '0;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------

    logic [5:0] rd_mux_addr;
    assign rd_mux_addr = decoded_addr;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_data_var = '0;
        if((rd_mux_addr == 6'h0) && (decoded_reg_strb.status)) begin
            readback_data_var[31:0] = field_storage.status.value.value;
        end
        if((rd_mux_addr == 6'h4) && (decoded_reg_strb.clkdiv)) begin
            readback_data_var[31:0] = field_storage.clkdiv.value.value;
        end
        if((rd_mux_addr == 6'h8) && (decoded_reg_strb.spicmd)) begin
            readback_data_var[31:0] = field_storage.spicmd.value.value;
        end
        if((rd_mux_addr == 6'hc) && (decoded_reg_strb.spiadr)) begin
            readback_data_var[31:0] = field_storage.spiadr.value.value;
        end
        if((rd_mux_addr == 6'h10) && (decoded_reg_strb.spilen)) begin
            readback_data_var[31:0] = field_storage.spilen.value.value;
        end
        if((rd_mux_addr == 6'h14) && (decoded_reg_strb.spidum)) begin
            readback_data_var[31:0] = field_storage.spidum.value.value;
        end
        if((rd_mux_addr == 6'h20) && (decoded_reg_strb.rxfifo)) begin
            readback_data_var[31:0] = field_storage.rxfifo.value.value;
        end
        if((rd_mux_addr == 6'h24) && (decoded_reg_strb.intcfg)) begin
            readback_data_var[31:0] = field_storage.intcfg.value.value;
        end
        if((rd_mux_addr == 6'h28) && (decoded_reg_strb.intsta)) begin
            readback_data_var[31:0] = field_storage.intsta.value.value;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
